import { useId, type ReactNode } from "react";

type SocialIconProps = {
  id: "yt" | "fb" | "ig" | "in";
  width: number;
  height: number;
};

function IconFrame({
  width,
  height,
  viewBox,
  children,
}: {
  width: number;
  height: number;
  viewBox: string;
  children: ReactNode;
}) {
  const rawId = useId().replace(/:/g, "");
  const shapeId = `social-shape-${rawId}`;
  const gradientId = `social-fill-${rawId}`;

  return (
    <svg
      width={width}
      height={height}
      viewBox={viewBox}
      fill="none"
      aria-hidden
      focusable="false"
    >
      <defs>
        <linearGradient id={gradientId} x1="0%" y1="0%" x2="100%" y2="0%">
          <stop offset="0%" stopColor="var(--gradient-winter-from)" />
          <stop offset="100%" stopColor="var(--gradient-winter-to)" />
        </linearGradient>
        <g id={shapeId}>{children}</g>
      </defs>
      <use href={`#${shapeId}`} className="social-icon-base" fill="currentColor" />
      <use
        href={`#${shapeId}`}
        className="social-icon-fill"
        fill={`url(#${gradientId})`}
      />
    </svg>
  );
}

